export function mountSignaturePad(root,name,onChange=()=>{}){
 const host=document.createElement('div');host.className='signature-pad';const title=document.createElement('h4');title.textContent='ลายเซ็นผู้เข้าร่วม: '+name;const hint=document.createElement('p');hint.className='sub';hint.textContent='ให้ผู้เข้าร่วมตรวจชื่อ แล้วใช้นิ้วหรือปากกาเซ็นในกรอบ';const canvas=document.createElement('canvas');canvas.width=800;canvas.height=480;canvas.className='signature-canvas';canvas.setAttribute('aria-label','พื้นที่ลงลายเซ็นของ '+name);const tools=document.createElement('div'),clear=document.createElement('button');clear.type='button';clear.textContent='ล้างลายเซ็น / เซ็นใหม่';tools.append(clear);const label=document.createElement('label');label.className='signature-consent';const consent=document.createElement('input');consent.type='checkbox';label.append(consent,document.createTextNode(' ข้าพเจ้ายืนยันการเข้าร่วมกิจกรรม และรับทราบว่าจะเก็บลายเซ็นนี้ประกอบหลักฐานการเข้าร่วมและการเบิกจ่ายของกิจกรรม'));host.append(title,hint,canvas,tools,label);root.append(host);
 const ctx=canvas.getContext('2d');let disabled=false,point=null,pointer=null,distance=0,captureId;
 const reset=()=>{point=null;pointer=null;distance=0;captureId=crypto.randomUUID();consent.checked=false;ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);onChange()};
 function position(event){const rect=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(canvas.width,(event.clientX-rect.left)*canvas.width/rect.width)),y:Math.max(0,Math.min(canvas.height,(event.clientY-rect.top)*canvas.height/rect.height))}}
 canvas.onpointerdown=event=>{if(disabled||event.isPrimary===false||event.button>0)return;event.preventDefault();pointer=event.pointerId;point=position(event);canvas.setPointerCapture?.(pointer);onChange()};
 canvas.onpointermove=event=>{if(disabled||!point||event.pointerId!==pointer)return;event.preventDefault();const next=position(event);ctx.beginPath();ctx.strokeStyle='#1646A0';ctx.lineWidth=5;ctx.lineCap='round';ctx.lineJoin='round';ctx.moveTo(point.x,point.y);ctx.lineTo(next.x,next.y);ctx.stroke();distance+=Math.hypot(next.x-point.x,next.y-point.y);point=next};
 const end=event=>{if(event.pointerId!==pointer)return;point=null;try{canvas.releasePointerCapture?.(pointer)}catch{}pointer=null;onChange()};canvas.onpointerup=end;canvas.onpointercancel=end;consent.onchange=onChange;clear.onclick=()=>{if(!disabled)reset()};reset();
 return {get valid(){return distance>=30&&consent.checked&&!point},value(){if(!this.valid)throw new Error('กรุณาลงลายเซ็นและยืนยันการเข้าร่วมก่อนบันทึก');return {captureId,consent:true,signaturePng:canvas.toDataURL('image/png')}},setDisabled(value){disabled=value;clear.disabled=consent.disabled=value;canvas.setAttribute('aria-disabled',String(value))},dispose(){ctx.clearRect(0,0,canvas.width,canvas.height);host.remove()}};
}
export async function viewSignature(client,eventId,applicationId,isCurrent=()=>true){
 const modal=document.querySelector('#modal'),body=document.querySelector('#modalBody');body.replaceChildren();delete modal.dataset.applicationId;const host=document.createElement('section'),title=document.createElement('h2'),status=document.createElement('p'),close=document.createElement('button');title.textContent='ลายเซ็นที่บันทึกแล้ว';status.textContent='กำลังโหลด…';close.type='button';close.textContent='ปิด';close.onclick=()=>modal.close();host.append(title,status,close);body.append(host);modal.addEventListener('close',()=>{if(body.contains(host))body.replaceChildren()},{once:true});modal.showModal();
 try{const data=await client.signCheckin({action:'view',eventId,applicationId});if(!isCurrent()||!modal.open||!body.contains(host))return;status.textContent=data.signerName+(data.recordedAtMs?' · '+new Date(data.recordedAtMs).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}):'');const img=document.createElement('img');img.className='signature-image';img.alt='ลายเซ็นของ '+data.signerName;img.src=data.signaturePng;host.insertBefore(img,close)}catch(error){if(isCurrent()&&body.contains(host))status.textContent=error.message||'โหลดลายเซ็นไม่ได้'}
}

